25	/// Whether each of `packages` changed since its last tag: a directory of the package holds different files than it did
26	/// at the tag, or its tracked files have uncommitted changes. An untagged package counts as changed. A change that was
27	/// made and then reverted leaves the package as it was released, so it is not a change.
28	///
29	/// Directories are compared by git tree id, all asked for in one `git cat-file --batch-check`, so the cost does not
30	/// grow with the number of commits. Uncommitted changes come from one `git diff`.
31	pub fn changed_since_last_tag(
32	    packages: &[&Package],
33	    tags: &TagIndex,
34	    git: &GitAccess<'_>,
35	) -> Result<BTreeMap<PackageId, bool>, GraphError> {
36	    let mut changed = BTreeMap::new();
37	    let mut tagged = Vec::new();
38	    for pkg in packages {
39	        match tags.last_tag(&pkg.id) {
40	            Some(last) => tagged.push((*pkg, last.name.as_str())),
41	            None => {
42	                changed.insert(pkg.id.clone(), true);
43	            }
44	        }
45	    }
46	    if tagged.is_empty() {
47	        return Ok(changed);
48	    }
49	
50	    let specs: Vec<Vec<PathBuf>> = tagged.iter().map(|(pkg, _)| package_paths(pkg)).collect();
51	    let mut differs = vec![false; tagged.len()];
52	    // Each package directory is asked for twice, at its tag and at `HEAD`; `pair_owners` says whose pair it is.
53	    let mut objects = Vec::new();
54	    let mut pair_owners = Vec::new();
55	    for (index, ((_, tag), directories)) in tagged.iter().zip(&specs).enumerate() {
56	        let Some(commit) = tags.commit_of(git, tag)? else {
57	            // A tag that does not end at a commit cannot be compared, so the package is proposed for release.
58	            differs[index] = true;
59	            continue;
60	        };
61	        for directory in directories {
62	            // `./` anchors the path at the working directory; a bare `rev:path` resolves from the repository top.
63	            let directory = if directory.as_path() == Path::new(".") {
64	                "./".to_owned()
65	            } else {
66	                format!("./{}", directory.to_string_lossy())
67	            };
68	            objects.push(format!("{}:{directory}", commit.as_str()));
69	            objects.push(format!("HEAD:{directory}"));
70	            pair_owners.push(index);
71	        }
72	    }
73	    let ids = git.object_ids(&objects)?;
74	    for (pair, &owner) in pair_owners.iter().enumerate() {
75	        if ids[2 * pair] != ids[2 * pair + 1] {
76	            differs[owner] = true;
77	        }
78	    }
79	
80	    // Uncommitted changes count for every package they touch; a diff that could not run counts as changed.
81	    let uncommitted = match git.paths_differing_from("HEAD") {
82	        Ok(paths) => Some(paths),
83	        Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
84	        Err(_) => None,
85	    };
86	    let owners = SpecIndex::new(&specs);
87	    let mut dirty = vec![uncommitted.is_none(); tagged.len()];
88	    for path in uncommitted.iter().flatten() {
89	        owners.owners_of(path, |package| dirty[package] = true);
90	    }
91	    for (index, (pkg, _)) in tagged.iter().enumerate() {
92	        changed.insert(pkg.id.clone(), differs[index] || dirty[index]);
93	    }
94	    Ok(changed)
95	}
