97	/// Paths whose edits do not change what ships: tests, benches, examples, snapshots and Markdown.
98	pub const DEFAULT_IGNORED_PATHS: &[&str] = &["tests/", "benches/", "examples/", "*.snap", "*.md", "CHANGELOG.md"];
99	
100	/// Files under each package's directories that differ between its last tag and `HEAD` or the working tree, minus the
101	/// `ignore` pathspecs (a trailing `/` names a directory at any depth, anything else a file glob). An untagged package, or
102	/// one whose tag is not a commit, yields all its tracked files. One git invocation per distinct tag commit, plus one per
103	/// untagged package.
104	pub fn changed_source_files_since_last_tag(
105	    packages: &[&Package],
106	    tags: &TagIndex,
107	    git: &GitAccess<'_>,
108	    ignore: &[&str],
109	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
110	    changed_source_files_in_batches(packages, tags, git, ignore, PATHSPEC_BUDGET)
111	}
112	
113	/// The most pathspec bytes one `git diff` gets, so a very large workspace stays under a command-line length limit
114	/// (32 KB on Windows) by splitting into a few diffs instead of one.
115	const PATHSPEC_BUDGET: usize = 24_000;
116	
117	fn changed_source_files_in_batches(
118	    packages: &[&Package],
119	    tags: &TagIndex,
120	    git: &GitAccess<'_>,
121	    ignore: &[&str],
122	    budget: usize,
123	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
124	    let excludes: Vec<String> = ignore.iter().map(|pattern| exclude_pathspec(pattern)).collect();
125	    let mut result = BTreeMap::new();
126	    let mut by_base: BTreeMap<String, Vec<(&Package, Vec<PathBuf>)>> = BTreeMap::new();
127	    for pkg in packages {
128	        let base = match tags.last_tag(&pkg.id) {
129	            Some(last) => tags.commit_of(git, last.name.as_str())?,
130	            None => None,
131	        };
132	        let directories = package_paths(pkg);
133	        match base {
134	            // With no directory the pathspec would be empty and match everything, so it is not batched.
135	            Some(commit) if !directories.is_empty() => {
136	                by_base
137	                    .entry(commit.as_str().to_owned())
138	                    .or_default()
139	                    .push((pkg, directories));
140	            }
141	            Some(commit) => {
142	                let files = list_files(git, &diff_command(commit.as_str()), &directories, &excludes)?;
143	                result.insert(pkg.id.clone(), files.into_iter().collect());
144	            }
145	            None => {
146	                let files = list_files(git, &["ls-files", "-z"], &directories, &excludes)?;
147	                result.insert(pkg.id.clone(), files.into_iter().collect());
148	            }
149	        }
150	    }
151	    for (commit, group) in &by_base {
152	        let specs: Vec<Vec<PathBuf>> = group.iter().map(|(_, directories)| directories.clone()).collect();
153	        let all: Vec<PathBuf> = specs.iter().flatten().cloned().collect();
154	        let listed = list_in_chunks(git, &diff_command(commit), &all, &excludes, budget)?;
155	        // A file belongs to every package whose directory contains it, as it did when each package had its own diff.
156	        let index = SpecIndex::new(&specs);
157	        let mut owned: Vec<BTreeSet<PathBuf>> = vec![BTreeSet::new(); group.len()];
158	        for path in listed {
159	            index.owners_of(&path, |package| {
160	                owned[package].insert(path.clone());
161	            });
162	        }
163	        for ((pkg, _), files) in group.iter().zip(owned) {
164	            result.insert(pkg.id.clone(), files.into_iter().collect());
165	        }
166	    }
167	    Ok(result)
168	}
169	
170	fn diff_command(commit: &str) -> [&str; 6] {
171	    ["diff", "--no-renames", "--relative", "--name-only", "-z", commit]
172	}
173	
174	/// `list_files` over `directories`, split so no command carries more than `budget` bytes of pathspec.
175	fn list_in_chunks(
176	    git: &GitAccess<'_>,
177	    command: &[&str],
178	    directories: &[PathBuf],
179	    excludes: &[String],
180	    budget: usize,
181	) -> Result<BTreeSet<PathBuf>, GraphError> {
182	    let fixed: usize = excludes.iter().map(|exclude| exclude.len() + 1).sum();
183	    let mut listed = BTreeSet::new();
184	    let mut start = 0;
185	    while start < directories.len() {
186	        let mut end = start;
187	        let mut bytes = fixed;
188	        while end < directories.len() && (end == start || bytes + directories[end].as_os_str().len() < budget) {
189	            bytes += directories[end].as_os_str().len() + 1;
190	            end += 1;
191	        }
192	        listed.extend(list_files(git, command, &directories[start..end], excludes)?);
193	        start = end;
194	    }
195	    Ok(listed)
196	}
197	
198	/// The paths `git <command> -- <directories> <excludes>` prints, which is NUL-separated.
199	fn list_files(
200	    git: &GitAccess<'_>,
201	    command: &[&str],
202	    directories: &[PathBuf],
203	    excludes: &[String],
204	) -> Result<BTreeSet<PathBuf>, GraphError> {
205	    let mut args: Vec<String> = command.iter().map(|arg| (*arg).to_owned()).collect();
206	    args.push("--".to_owned());
207	    args.extend(directories.iter().map(|d| d.to_string_lossy().into_owned()));
208	    args.extend(excludes.iter().cloned());
209	    let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
210	    let output = git.runner().run("git", &arg_refs, git.root()).map_err(VcsError::from)?;
211	    if !output.success() {
212	        return Err(VcsError::Git(format!(
213	            "`git {}` failed in `{}`: {}",
214	            args[0],
215	            git.root().display(),
216	            output.redacted_stderr()
217	        ))
218	        .into());
219	    }
220	    Ok(output
221	        .stdout
222	        .split('\0')
223	        .map(|path| path.trim_start_matches('\n'))
224	        .filter(|path| !path.is_empty())
225	        .map(PathBuf::from)
226	        .collect())
227	}
228	
229	fn exclude_pathspec(pattern: &str) -> String {
230	    match pattern.strip_suffix('/') {
231	        Some(directory) => format!(":(exclude,glob)**/{directory}/**"),
232	        None => format!(":(exclude,glob)**/{pattern}"),
233	    }
234	}
