236	/// Whether `id` is released with `covered`: it is covered itself, or a member of its fixed or linked group is, since a
237	/// group moves together.
238	pub fn is_covered(id: &PackageId, covered: &BTreeSet<PackageId>, groups: &GroupTable) -> bool {
239	    covered.contains(id)
240	        || [(&groups.fixed_of, &groups.fixed), (&groups.linked_of, &groups.linked)]
241	            .into_iter()
242	            .filter_map(|(of, defs)| of.get(id).and_then(|name| defs.get(name)))
243	            .any(|group| group.package_members().any(|member| covered.contains(member)))
244	}
245	
246	/// Packages with a changed source file that nothing releases: not [covered](is_covered).
247	pub fn uncovered_changes(
248	    changed: &BTreeMap<PackageId, Vec<PathBuf>>,
249	    covered: &BTreeSet<PackageId>,
250	    groups: &GroupTable,
251	) -> Vec<PackageId> {
252	    changed
253	        .iter()
254	        .filter(|(id, files)| !files.is_empty() && !is_covered(id, covered, groups))
255	        .map(|(id, _)| id.clone())
256	        .collect()
257	}
258	
259	/// The changed source files of the packages in `packages` that nothing releases, without a git process per package.
260	/// Covered packages are skipped outright, whether or not they changed; the rest are told apart by tree id in a fixed
261	/// number of processes, and only a package that really changed pays for its own file listing.
262	pub fn changed_source_files_of_uncovered(
263	    packages: &[&Package],
264	    tags: &TagIndex,
265	    git: &GitAccess<'_>,
266	    covered: &BTreeSet<PackageId>,
267	    groups: &GroupTable,
268	    ignore: &[&str],
269	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
270	    let candidates: Vec<&Package> = packages
271	        .iter()
272	        .copied()
273	        .filter(|package| !is_covered(&package.id, covered, groups))
274	        .collect();
275	    let touched = changed_since_last_tag(&candidates, tags, git)?;
276	    let changed: Vec<&Package> = candidates
277	        .into_iter()
278	        .filter(|package| touched.get(&package.id).copied().unwrap_or(false))
279	        .collect();
280	    changed_source_files_since_last_tag(&changed, tags, git, ignore)
281	}
