283	/// Which packages a path belongs to: those with a spec that is an ancestor directory of it, and those with the `.`
284	/// spec, which every path falls under.
285	struct SpecIndex<'a> {
286	    by_directory: std::collections::HashMap<&'a Path, Vec<usize>>,
287	    everywhere: Vec<usize>,
288	}
289	
290	impl<'a> SpecIndex<'a> {
291	    fn new(specs: &'a [Vec<PathBuf>]) -> Self {
292	        let mut by_directory: std::collections::HashMap<&Path, Vec<usize>> = std::collections::HashMap::new();
293	        let mut everywhere = Vec::new();
294	        for (package, package_specs) in specs.iter().enumerate() {
295	            for spec in package_specs {
296	                if spec.as_path() == Path::new(".") {
297	                    everywhere.push(package);
298	                } else {
299	                    by_directory.entry(spec.as_path()).or_default().push(package);
300	                }
301	            }
302	        }
303	        SpecIndex {
304	            by_directory,
305	            everywhere,
306	        }
307	    }
308	
309	    fn owners_of(&self, path: &Path, mut found: impl FnMut(usize)) {
310	        for &package in &self.everywhere {
311	            found(package);
312	        }
313	        for directory in path.ancestors() {
314	            for &package in self.by_directory.get(directory).into_iter().flatten() {
315	                found(package);
316	            }
317	        }
318	    }
319	}
