863	    fn per_package_reference(root: &Path, pkgs: &[Package]) -> BTreeMap<PackageId, Vec<PathBuf>> {
864	        let excludes: Vec<String> = DEFAULT_IGNORED_PATHS.iter().map(|p| exclude_pathspec(p)).collect();
865	        pkgs.iter()
866	            .map(|pkg| {
867	                let tag = format!("{}@1.0.0", pkg.id);
868	                let tagged = run_git_ok(root, &["rev-parse", "-q", "--verify", &format!("{tag}^{{commit}}")]);
869	                let mut args: Vec<String> = match &tagged {
870	                    Some(commit) => [
871	                        "diff",
872	                        "--no-renames",
873	                        "--relative",
874	                        "--name-only",
875	                        "-z",
876	                        commit.trim(),
877	                        "--",
878	                    ]
879	                    .map(String::from)
880	                    .to_vec(),
881	                    None => ["ls-files", "-z", "--"].map(String::from).to_vec(),
882	                };
883	                args.extend(package_paths(pkg).iter().map(|d| d.to_string_lossy().into_owned()));
884	                args.extend(excludes.iter().cloned());
885	                let refs: Vec<&str> = args.iter().map(String::as_str).collect();
886	                let output = GitRunner.run("git", &refs, root).unwrap();
887	                let files: BTreeSet<PathBuf> = output
888	                    .stdout
889	                    .split('\0')
890	                    .filter(|path| !path.is_empty())
891	                    .map(PathBuf::from)
892	                    .collect();
893	                (pkg.id.clone(), files.into_iter().collect())
894	            })
895	            .collect()
896	    }
