fn sources(root: &Path, pkgs: &[Package], ignore: &[&str]) -> BTreeMap<PackageId, Vec<PathBuf>> {
    let graph = FixedGraph { pkgs: pkgs.to_vec() };
    let cfg = crate::config::load(root).unwrap();
